using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.IO;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;

namespace SecureAuth.Library
{
    public class EncryptedSessionStore
    {
        private readonly ConcurrentDictionary<string, EncryptedSessionData> _sessions = new();
        private readonly byte[] _masterKey;

        public EncryptedSessionStore(byte[] masterKey)
        {
            _masterKey = masterKey;
        }

        public string CreateSession()
        {
            var sessionId = GenerateSessionId();
            _sessions[sessionId] = new EncryptedSessionData();
            return sessionId;
        }

        public void SetEncryptedValue(string sessionId, string key, string value)
        {
            if (_sessions.TryGetValue(sessionId, out var data))
            {
                var encrypted = EncryptValue(value, DeriveSessionKey(sessionId));
                data.Store[key] = encrypted;
            }
        }

        public string GetDecryptedValue(string sessionId, string key)
        {
            if (_sessions.TryGetValue(sessionId, out var data) && data.Store.ContainsKey(key))
            {
                return DecryptValue(data.Store[key], DeriveSessionKey(sessionId));
            }
            return null;
        }

        public bool MigrateSession(string oldSessionId, string newSessionId)
        {
            if (_sessions.TryGetValue(oldSessionId, out var oldData))
            {
                var newData = new EncryptedSessionData();
                var oldKey = DeriveSessionKey(oldSessionId);
                var newKey = DeriveSessionKey(newSessionId);
                foreach (var kvp in oldData.Store)
                {
                    var plaintext = DecryptValue(kvp.Value, oldKey);
                    newData.Store[kvp.Key] = EncryptValue(plaintext, newKey);
                }
                _sessions[newSessionId] = newData;
                return true;
            }
            return false;
        }

        public void DestroySession(string sessionId)
        {
            _sessions.TryRemove(sessionId, out _);
        }

        private byte[] DeriveSessionKey(string sessionId)
        {
            using var hmac = new HMACSHA256(_masterKey);
            return hmac.ComputeHash(Encoding.UTF8.GetBytes(sessionId));
        }

        private string GenerateSessionId()
        {
            var bytes = new byte[32];
            using var rng = RandomNumberGenerator.Create();
            rng.GetBytes(bytes);
            return Convert.ToBase64String(bytes);
        }

        private byte[] EncryptValue(string plaintext, byte[] key)
        {
            using var aes = Aes.Create();
            aes.Key = key;
            aes.GenerateIV();
            using var encryptor = aes.CreateEncryptor();
            var plaintextBytes = Encoding.UTF8.GetBytes(plaintext);
            var ciphertext = encryptor.TransformFinalBlock(plaintextBytes, 0, plaintextBytes.Length);
            var result = new byte[aes.IV.Length + ciphertext.Length];
            Buffer.BlockCopy(aes.IV, 0, result, 0, aes.IV.Length);
            Buffer.BlockCopy(ciphertext, 0, result, aes.IV.Length, ciphertext.Length);
            return result;
        }

        private string DecryptValue(byte[] ciphertext, byte[] key)
        {
            using var aes = Aes.Create();
            aes.Key = key;
            var iv = new byte[16];
            Buffer.BlockCopy(ciphertext, 0, iv, 0, 16);
            aes.IV = iv;
            using var decryptor = aes.CreateDecryptor();
            var plaintext = decryptor.TransformFinalBlock(ciphertext, 16, ciphertext.Length - 16);
            return Encoding.UTF8.GetString(plaintext);
        }
    }

    public class EncryptedSessionData
    {
        public ConcurrentDictionary<string, byte[]> Store { get; } = new();
    }

    [ApiController]
    [Route("api/auth")]
    public class AuthController : ControllerBase
    {
        private readonly EncryptedSessionStore _sessionStore;
        private readonly IUserService _userService;

        public AuthController(EncryptedSessionStore sessionStore, IUserService userService)
        {
            _sessionStore = sessionStore;
            _userService = userService;
        }

        [HttpPost("login")]
        public IActionResult Login([FromBody] LoginRequest request)
        {
            var user = _userService.ValidateCredentials(request.Username, request.Password);
            if (user == null)
                return Unauthorized();

            var currentSessionId = GetOrCreateSessionId();
            var newSessionId = RegenerateSessionIdentifier(currentSessionId);

            _sessionStore.SetEncryptedValue(newSessionId, "user_id", user.Id.ToString());
            _sessionStore.SetEncryptedValue(newSessionId, "auth_level", "authenticated");
            _sessionStore.SetEncryptedValue(newSessionId, "login_time", DateTime.UtcNow.ToString("O"));

            SetSessionCookie(newSessionId);
            return Ok(new { message = "Login successful" });
        }

        [HttpPost("logout")]
        public IActionResult Logout()
        {
            var sessionId = GetSessionIdFromCookie();
            if (sessionId != null)
            {
                _sessionStore.DestroySession(sessionId);
                Response.Cookies.Delete("SESSIONID");
            }
            return Ok();
        }

        private string RegenerateSessionIdentifier(string currentSessionId)
        {
            var newSessionId = _sessionStore.CreateSession();
            if (currentSessionId != null)
            {
                _sessionStore.MigrateSession(currentSessionId, newSessionId);
                // Note: old session preserved for graceful connection handling
                // Cleanup handled by background expiration service
            }
            return newSessionId;
        }

        private string GetOrCreateSessionId()
        {
            var sessionId = GetSessionIdFromCookie();
            if (sessionId == null)
            {
                sessionId = _sessionStore.CreateSession();
                SetSessionCookie(sessionId);
            }
            return sessionId;
        }

        private string GetSessionIdFromCookie()
        {
            return Request.Cookies["SESSIONID"];
        }

        private void SetSessionCookie(string sessionId)
        {
            Response.Cookies.Append("SESSIONID", sessionId, new CookieOptions
            {
                HttpOnly = true,
                Secure = true,
                SameSite = SameSiteMode.Strict,
                MaxAge = TimeSpan.FromHours(8)
            });
        }
    }

    public interface IUserService
    {
        UserInfo ValidateCredentials(string username, string password);
    }

    public class UserInfo
    {
        public int Id { get; set; }
        public string Username { get; set; }
    }

    public class LoginRequest
    {
        public string Username { get; set; }
        public string Password { get; set; }
    }
}
